def U_i(positions, sigma, epsilon):
    return 4 * epsilon * ((sigma / np.linalg.norm(positions)) ** 12 - (sigma / np.linalg.norm(positions)) ** 6)

def U_system(positions, sigma, epsilon):
    total_energy = 0
    for i in range(len(positions)):
        for j in range(i+1, len(positions)):
            total_energy += U_i(positions[i] - positions[j], sigma, epsilon)
    return total_energy

def MC(sigma, epsilon, T, init_positions, MC_steps, dispSize):
    beta = 1 / T
    E_trace = []
    current_positions = init_positions.copy()
    for _ in range(MC_steps):
        i = np.random.randint(0, len(current_positions))
        new_position = current_positions[i] + np.random.normal(0, dispSize)
        new_energy = U_system(new_position, sigma, epsilon)
        acceptance_ratio = min(1, np.exp(-beta * (new_energy - E_trace[-1])))
        if np.random.rand() < acceptance_ratio:
            current_positions[i] = new_position
        E_trace.append(U_system(current_positions, sigma, epsilon))
    return np.array(E_trace)
